from pathlib import Path

worker = Path('trader/worker.py')
text = worker.read_text()
anchor = '''def free_quote_balance(client: BinanceSpotClient, quote_asset: str) -> Decimal:\n    for balance in client.account().get("balances", []):\n        if balance.get("asset") == quote_asset:\n            return Decimal(str(balance.get("free", "0")))\n    return Decimal("0")\n\n\n'''
addition = '''def free_quote_balance(client: BinanceSpotClient, quote_asset: str) -> Decimal:\n    for balance in client.account().get("balances", []):\n        if balance.get("asset") == quote_asset:\n            return Decimal(str(balance.get("free", "0")))\n    return Decimal("0")\n\n\ndef binance_account_summary(client: BinanceSpotClient, quote_asset: str) -> tuple[str, Decimal, Decimal]:\n    account = client.account()\n    balances = {\n        str(row.get("asset")): Decimal(str(row.get("free", "0"))) + Decimal(str(row.get("locked", "0")))\n        for row in account.get("balances", [])\n        if Decimal(str(row.get("free", "0"))) + Decimal(str(row.get("locked", "0"))) > 0\n    }\n    tickers = client._request("GET", "/api/v3/ticker/price")\n    prices = {str(row.get("symbol")): Decimal(str(row.get("price", "0"))) for row in tickers}\n\n    def in_quote(asset: str) -> Decimal | None:\n        if asset == quote_asset:\n            return Decimal("1")\n        direct = prices.get(f"{asset}{quote_asset}")\n        if direct and direct > 0:\n            return direct\n        if quote_asset == "USDC":\n            if asset == "USDT":\n                usdc_usdt = prices.get("USDCUSDT")\n                if usdc_usdt and usdc_usdt > 0:\n                    return Decimal("1") / usdc_usdt\n                usdt_usdc = prices.get("USDTUSDC")\n                if usdt_usdc and usdt_usdc > 0:\n                    return usdt_usdc\n            via_usdt = prices.get(f"{asset}USDT")\n            usdc_usdt = prices.get("USDCUSDT")\n            if via_usdt and via_usdt > 0 and usdc_usdt and usdc_usdt > 0:\n                return via_usdt / usdc_usdt\n            via_btc = prices.get(f"{asset}BTC")\n            btc_quote = prices.get("BTCUSDC")\n            if via_btc and via_btc > 0 and btc_quote and btc_quote > 0:\n                return via_btc * btc_quote\n        elif quote_asset == "USDT":\n            if asset == "USDC":\n                usdc_usdt = prices.get("USDCUSDT")\n                if usdc_usdt and usdc_usdt > 0:\n                    return usdc_usdt\n            via_usdc = prices.get(f"{asset}USDC")\n            usdc_usdt = prices.get("USDCUSDT")\n            if via_usdc and via_usdc > 0 and usdc_usdt and usdc_usdt > 0:\n                return via_usdc * usdc_usdt\n            via_btc = prices.get(f"{asset}BTC")\n            btc_quote = prices.get("BTCUSDT")\n            if via_btc and via_btc > 0 and btc_quote and btc_quote > 0:\n                return via_btc * btc_quote\n        return None\n\n    total = Decimal("0")\n    invested = Decimal("0")\n    for asset, quantity in balances.items():\n        conversion = in_quote(asset)\n        if conversion is None:\n            continue\n        value = quantity * conversion\n        total += value\n        if asset != quote_asset:\n            invested += value\n    balance_text = ",".join(f"{asset}:{quantity}" for asset, quantity in balances.items()) or "none"\n    return balance_text, total, invested\n\n\n'''
if anchor not in text:
    raise SystemExit('worker summary anchor not found')
text = text.replace(anchor, addition, 1)
old_hb = '''                price_text = ",".join(f"{pair}:{client.ticker_price(pair)}" for pair in pairs)\n                reporter.record_event(\n                    "heartbeat",\n                    f"live={allow_new_entries};available={available_balance};quote={quote_asset};{context};"\n                    f"signals={signal_text};scores={score_text};scalp_scores={scalp_score_text};"\n                    f"prices={price_text};balances={balance_text};markets={','.join(pairs)};"\n'''
new_hb = '''                price_text = ",".join(f"{pair}:{client.ticker_price(pair)}" for pair in pairs)\n                balance_text, account_total, invested_value = binance_account_summary(client, quote_asset)\n                reporter.record_event(\n                    "heartbeat",\n                    f"live={allow_new_entries};available={available_balance};quote={quote_asset};{context};"\n                    f"signals={signal_text};scores={score_text};scalp_scores={scalp_score_text};"\n                    f"prices={price_text};balances={balance_text};account_total={account_total};invested_value={invested_value};markets={','.join(pairs)};"\n'''
if old_hb not in text:
    # tolerate earlier balance_text being constructed inline before reporter call
    old_hb2 = '''                price_text = ",".join(f"{pair}:{client.ticker_price(pair)}" for pair in pairs)\n                account = client.account()\n                balance_text = ",".join(\n                    f"{row.get('asset')}:{Decimal(str(row.get('free', '0'))) + Decimal(str(row.get('locked', '0')))}"\n                    for row in account.get("balances", [])\n                    if Decimal(str(row.get("free", "0"))) + Decimal(str(row.get("locked", "0"))) > 0\n                ) or "none"\n                reporter.record_event(\n                    "heartbeat",\n                    f"live={allow_new_entries};available={available_balance};quote={quote_asset};{context};"\n                    f"signals={signal_text};scores={score_text};scalp_scores={scalp_score_text};"\n                    f"prices={price_text};balances={balance_text};markets={','.join(pairs)};"\n'''
    if old_hb2 not in text:
        raise SystemExit('worker heartbeat block not found')
    text = text.replace(old_hb2, new_hb, 1)
else:
    text = text.replace(old_hb, new_hb, 1)
worker.write_text(text)

dash = Path('app/trading-dashboard.tsx')
text = dash.read_text()
old_summary = '''  const availableCapital = useMemo(() => {\n    const match = lastEvent?.message.match(/(?:^|;)available=([0-9.]+)/);\n    const value = match ? Number(match[1]) : Number.NaN;\n    return Number.isFinite(value) ? value : Number(settings.trade_cap_usdc);\n  }, [lastEvent, settings.trade_cap_usdc]);\n\n  const portfolioValue = useMemo(() => allocations.reduce((sum, allocation) =>\n    sum + (allocation.owned ? Number(allocation.currentValue ?? allocation.invested) : 0), 0), [allocations]);\n  const investedCost = useMemo(() => allocations.reduce((sum, allocation) =>\n    sum + (allocation.owned ? Number(allocation.invested) : 0), 0), [allocations]);\n  const totalAssets = availableCapital + portfolioValue;\n'''
new_summary = '''  const availableCapital = useMemo(() => {\n    const walletValue = binanceBalances.get(settings.quote_asset);\n    if (walletValue !== undefined && Number.isFinite(walletValue)) return walletValue;\n    const match = lastEvent?.message.match(/(?:^|;)available=([0-9.]+)/);\n    const value = match ? Number(match[1]) : Number.NaN;\n    return Number.isFinite(value) ? value : Number(settings.trade_cap_usdc);\n  }, [binanceBalances, lastEvent, settings.quote_asset, settings.trade_cap_usdc]);\n\n  const portfolioValue = useMemo(() => {\n    const match = lastEvent?.message.match(/(?:^|;)invested_value=([0-9.]+)/);\n    const value = match ? Number(match[1]) : Number.NaN;\n    if (Number.isFinite(value)) return value;\n    return allocations.reduce((sum, allocation) => sum + (allocation.owned ? Number(allocation.currentValue ?? 0) : 0), 0);\n  }, [allocations, lastEvent]);\n\n  const totalAssets = useMemo(() => {\n    const match = lastEvent?.message.match(/(?:^|;)account_total=([0-9.]+)/);\n    const value = match ? Number(match[1]) : Number.NaN;\n    return Number.isFinite(value) ? value : availableCapital + portfolioValue;\n  }, [availableCapital, lastEvent, portfolioValue]);\n'''
if old_summary not in text:
    raise SystemExit('dashboard summary block not found')
text = text.replace(old_summary, new_summary, 1)
text = text.replace('''<div><span className="label">TOTAL VERDI</span><strong style={{ display: "block", fontSize: "clamp(2.2rem, 5vw, 4.4rem)", lineHeight: 1.05, marginTop: 8 }}>{money(totalAssets)} {settings.quote_asset}</strong><small>Ledige midler + markedsverdi av åpne posisjoner</small></div>\n        <div><span className="label">Investert nå</span><strong style={{ display: "block", fontSize: "1.6rem", marginTop: 8 }}>{money(portfolioValue)} {settings.quote_asset}</strong><small>Kostpris: {money(investedCost)} {settings.quote_asset}</small></div>\n        <div><span className="label">Ikke investert</span><strong style={{ display: "block", fontSize: "1.6rem", marginTop: 8 }}>{money(availableCapital)} {settings.quote_asset}</strong><small>Fri saldo</small></div>''', '''<div><span className="label">TOTAL BINANCE-VERDI</span><strong style={{ display: "block", fontSize: "clamp(2.2rem, 5vw, 4.4rem)", lineHeight: 1.05, marginTop: 8 }}>{money(totalAssets)} {settings.quote_asset}</strong><small>Kun faktisk beholdning på Binance, verdsatt til markedspris</small></div>\n        <div><span className="label">Investert på Binance</span><strong style={{ display: "block", fontSize: "1.6rem", marginTop: 8 }}>{money(portfolioValue)} {settings.quote_asset}</strong><small>Faktisk krypto-beholdning nå</small></div>\n        <div><span className="label">Ledig på Binance</span><strong style={{ display: "block", fontSize: "1.6rem", marginTop: 8 }}>{money(availableCapital)} {settings.quote_asset}</strong><small>Faktisk fri {settings.quote_asset}-saldo</small></div>''')
dash.write_text(text)

Path('scripts/apply_binance_summary_fix.py').unlink(missing_ok=True)
Path('.github/workflows/apply-binance-summary-fix.yml').unlink(missing_ok=True)
